public sealed record OmsiTileObjectInsertResult(
    byte[] Bytes,
    int SourceSectionOrdinal);

using System.Globalization;
using MapStudio.Core.Omsi.Config;

namespace MapStudio.Core.Omsi.Maps;

public static class OmsiTileObjectInserter
{
    public static OmsiTileObjectInsertResult Append(
        OmsiConfigDocument document,
        OmsiNewPlacedObject placedObject)
    {
        ArgumentNullException.ThrowIfNull(document);
        ArgumentNullException.ThrowIfNull(placedObject);

        if (string.IsNullOrWhiteSpace(
                placedObject.HeaderValue) ||
            string.IsNullOrWhiteSpace(
                placedObject.SceneryObjectPath) ||
            placedObject.ObjectId <= 0 ||
            !IsFinite(placedObject))
        {
            throw new InvalidDataException(
                "invalidNewObject");
        }

        var lines =
            document.Lines.ToList();

        if (
            lines.Count > 0 &&
            lines[^1].Length != 0)
        {
            lines.Add(string.Empty);
        }

        var sourceSectionOrdinal =
            document
                .FindSections("object")
                .Count();

        lines.Add("[object]");
        lines.Add(
            placedObject.HeaderValue);
        lines.Add(
            placedObject
                .SceneryObjectPath);
        lines.Add(
            placedObject.ObjectId
                .ToString(
                    CultureInfo.InvariantCulture));
        lines.Add(Format(placedObject.X));
        lines.Add(Format(placedObject.Y));
        lines.Add(Format(placedObject.Z));
        lines.Add(
            Format(
                placedObject.Rotation));
        lines.Add(
            Format(
                placedObject.Pitch));
        lines.Add(
            Format(
                placedObject.Bank));

        foreach (var extra in
            placedObject.ExtraValues)
        {
            lines.Add(extra);
        }

        return new OmsiTileObjectInsertResult(
            Encode(document, lines),
            sourceSectionOrdinal);
    }

    private static bool IsFinite(
        OmsiNewPlacedObject value) =>
        double.IsFinite(value.X) &&
        double.IsFinite(value.Y) &&
        double.IsFinite(value.Z) &&
        double.IsFinite(
            value.Rotation) &&
        double.IsFinite(value.Pitch) &&
        double.IsFinite(value.Bank);

    private static string Format(
        double value) =>
        value.ToString(
            "G17",
            CultureInfo.InvariantCulture);

    private static byte[] Encode(
        OmsiConfigDocument document,
        IReadOnlyList<string> lines)
    {
        var text =
            string.Join(
                document.NewLine,
                lines);

        if (
            document.HasTrailingNewLine &&
            lines.Count > 0)
        {
            text += document.NewLine;
        }

        var body =
            document.TextEncoding
                .GetBytes(text);

        if (!document.HasByteOrderMark)
        {
            return body;
        }

        var preamble =
            document.TextEncoding
                .GetPreamble();

        if (preamble.Length == 0)
        {
            return body;
        }

        var result =
            new byte[
                preamble.Length +
                body.Length];

        Buffer.BlockCopy(
            preamble,
            0,
            result,
            0,
            preamble.Length);

        Buffer.BlockCopy(
            body,
            0,
            result,
            preamble.Length,
            body.Length);

        return result;
    }
}

using System.Globalization;
using MapStudio.Core.Omsi.Config;

namespace MapStudio.Core.Omsi.Maps;

public sealed class OmsiTileReader
{
    public async Task<OmsiTileContent> ReadContentAsync(
        string tilePath,
        CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(tilePath);

        if (!File.Exists(tilePath))
        {
            return OmsiTileContent.Missing;
        }

        var document =
            await OmsiConfigParser.ParseFileAsync(
                tilePath,
                cancellationToken);

        var content =
            ReadContent(
                document);

        var terrainPath =
            tilePath + ".terrain";

        var terrainFileExists =
            File.Exists(
                terrainPath);

        var terrainFileSize =
            terrainFileExists
                ? new FileInfo(
                    terrainPath)
                    .Length
                : 0;

        return content with
        {
            Summary =
                content.Summary with
                {
                    TerrainFileExists =
                        terrainFileExists,
                    TerrainFileSize =
                        terrainFileSize
                }
        };
    }

    public static OmsiTileContent ReadContent(
        OmsiConfigDocument document)
    {
        ArgumentNullException.ThrowIfNull(
            document);

        var attachmentCount =
            document.FindSections("splineAttachement").Count() +
            document.FindSections("splineAttachment").Count();

        var splineCount =
            document.FindSections("spline").Count() +
            document.FindSections("spline_h").Count();

        var summary = new OmsiTileSummary(
            Exists: true,
            ObjectCount:
                document.FindSections("object").Count(),
            SplineCount:
                splineCount,
            SplineAttachmentCount:
                attachmentCount,
            TerrainMarkerPresent:
                document.FindFirstSection(
                    "terrain") is not null);

        return new OmsiTileContent(
            summary,
            ReadObjects(document),
            ReadSplines(document));
    }

    public async Task<OmsiTileSummary> ReadSummaryAsync(
        string tilePath,
        CancellationToken cancellationToken = default) =>
        (await ReadContentAsync(
            tilePath,
            cancellationToken)).Summary;

    public async Task<IReadOnlyList<OmsiPlacedObject>>
        ReadObjectsAsync(
            string tilePath,
            CancellationToken cancellationToken = default) =>
        (await ReadContentAsync(
            tilePath,
            cancellationToken)).Objects;

    public static IReadOnlyList<OmsiPlacedObject> ReadObjects(
        OmsiConfigDocument document)
    {
        ArgumentNullException.ThrowIfNull(document);

        var objects = new List<OmsiPlacedObject>();

        var objectSections =
            document.FindSections("object")
                .ToArray();

        for (
            var sectionOrdinal = 0;
            sectionOrdinal < objectSections.Length;
            sectionOrdinal++)
        {
            var section =
                objectSections[sectionOrdinal];

            var values =
                section.DataLines.ToArray();

            if (values.Length < 9 ||
                !int.TryParse(
                    values[2],
                    NumberStyles.Integer,
                    CultureInfo.InvariantCulture,
                    out var objectId) ||
                !TryParseDouble(values[3], out var x) ||
                !TryParseDouble(values[4], out var y) ||
                !TryParseDouble(values[5], out var z) ||
                !TryParseDouble(
                    values[6],
                    out var rotation) ||
                !TryParseDouble(
                    values[7],
                    out var pitch) ||
                !TryParseDouble(
                    values[8],
                    out var bank))
            {
                continue;
            }

            objects.Add(new OmsiPlacedObject(
                HeaderValue: values[0],
                SceneryObjectPath: values[1],
                ObjectId: objectId,
                X: x,
                Y: y,
                Z: z,
                Rotation: rotation,
                Pitch: pitch,
                Bank: bank,
                ExtraValues:
                    values.Skip(9).ToArray())
                {
                    SourceSectionOrdinal =
                        sectionOrdinal
                });
        }

        return objects;
    }

    public static IReadOnlyList<OmsiPlacedSpline> ReadSplines(
        OmsiConfigDocument document)
    {
        ArgumentNullException.ThrowIfNull(document);

        var splines =
            new List<OmsiPlacedSpline>();

        var sourceSectionOrdinal = 0;

        foreach (var section in document.Sections)
        {
            var isSpline =
                string.Equals(
                    section.Keyword,
                    "spline",
                    StringComparison.OrdinalIgnoreCase);

            var isHeightSpline =
                string.Equals(
                    section.Keyword,
                    "spline_h",
                    StringComparison.OrdinalIgnoreCase);

            if (!isSpline && !isHeightSpline)
            {
                continue;
            }

            var currentSectionOrdinal =
                sourceSectionOrdinal++;

            var values =
                section.DataLines.ToArray();

            if (values.Length < 13 ||
                !int.TryParse(
                    values[2],
                    NumberStyles.Integer,
                    CultureInfo.InvariantCulture,
                    out var splineId) ||
                !int.TryParse(
                    values[3],
                    NumberStyles.Integer,
                    CultureInfo.InvariantCulture,
                    out var previousSplineId) ||
                !int.TryParse(
                    values[4],
                    NumberStyles.Integer,
                    CultureInfo.InvariantCulture,
                    out var nextSplineId) ||
                !TryParseDouble(values[5], out var x) ||
                !TryParseDouble(values[6], out var z) ||
                !TryParseDouble(values[7], out var y) ||
                !TryParseDouble(
                    values[8],
                    out var rotation) ||
                !TryParseDouble(
                    values[9],
                    out var length) ||
                !TryParseDouble(
                    values[10],
                    out var radius) ||
                !TryParseDouble(
                    values[11],
                    out var gradientStart) ||
                !TryParseDouble(
                    values[12],
                    out var gradientEnd))
            {
                continue;
            }

            splines.Add(new OmsiPlacedSpline(
                HeaderValue: values[0],
                SplinePath: values[1],
                SplineId: splineId,
                PreviousSplineId: previousSplineId,
                NextSplineId: nextSplineId,
                X: x,
                Z: z,
                Y: y,
                Rotation: rotation,
                Length: length,
                Radius: radius,
                GradientStart: gradientStart,
                GradientEnd: gradientEnd,
                IsHeightSpline: isHeightSpline,
                ExtraValues:
                    values.Skip(13).ToArray())
                {
                    SourceSectionOrdinal =
                        currentSectionOrdinal
                });
        }

        return splines;
    }

    private static bool TryParseDouble(
        string value,
        out double result) =>
        double.TryParse(
            value,
            NumberStyles.Float,
            CultureInfo.InvariantCulture,
            out result);
}

